import { test, expect } from '@playwright/test';

test.describe('Search Race Condition Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display only the latest search result when multiple requests are in flight', async ({ page }) => {
    // Intercept the search API endpoint
    await page.route('**/api/search', (route) => {
      const request = route.request();
      const query = request.url().split('q=')[1];

      if (query === 'apple') {
        // Simulate a slow response for the first request
        setTimeout(() => {
          route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ results: [{ id: 1, name: 'Apple iPhone 14' }] }),
          });
        }, 1500);
      } else if (query === 'banana') {
        // Simulate a fast response for the second request
        setTimeout(() => {
          route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ results: [{ id: 2, name: 'Banana Split' }] }),
          });
        }, 300);
      } else if (query === 'apple again') {
        // Simulate a third, even slower response
        setTimeout(() => {
          route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ results: [{ id: 3, name: 'Apple Watch Series 7' }] }),
          });
        }, 2500);
      }
    });

    // First search: 'apple'
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('apple');
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Second search: 'banana' (should complete before first)
    await searchInput.fill('banana');
    await searchButton.click();

    // Third search: 'apple again' (should be the final result)
    await searchInput.fill('apple again');
    await searchButton.click();

    // Wait for all requests to settle
    await page.waitForTimeout(3000);

    // Verify only the latest result is displayed
    const resultItem = page.getByText('Apple Watch Series 7');
    await expect(resultItem).toBeVisible();

    // Verify the previous results are not visible
    const appleResult = page.getByText('Apple iPhone 14');
    await expect(appleResult).not.toBeVisible();

    const bananaResult = page.getByText('Banana Split');
    await expect(bananaResult).not.toBeVisible();
  });

  test('should handle rapid successive searches without displaying stale results', async ({ page }) => {
    // Intercept the search API endpoint
    await page.route('**/api/search', (route) => {
      const request = route.request();
      const query = request.url().split('q=')[1];

      if (query === 'test1') {
        setTimeout(() => {
          route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ results: [{ id: 101, name: 'Test Result 1' }] }),
          });
        }, 1000);
      } else if (query === 'test2') {
        setTimeout(() => {
          route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ results: [{ id: 201, name: 'Test Result 2' }] }),
          });
        }, 500);
      } else if (query === 'test3') {
        setTimeout(() => {
          route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ results: [{ id: 301, name: 'Test Result 3' }] }),
          });
        }, 100);
      }
    });

    // Rapidly trigger three searches
    const searchInput = page.getByRole('searchbox');
    const searchButton = page.getByRole('button', { name: /search/i });

    await searchInput.fill('test1');
    await searchButton.click();

    await searchInput.fill('test2');
    await searchButton.click();

    await searchInput.fill('test3');
    await searchButton.click();

    // Wait briefly for all requests to complete
    await page.waitForTimeout(1500);

    // Verify only the latest result is displayed
    const latestResult = page.getByText('Test Result 3');
    await expect(latestResult).toBeVisible();

    // Verify previous results are not visible
    const result1 = page.getByText('Test Result 1');
    await expect(result1).not.toBeVisible();

    const result2 = page.getByText('Test Result 2');
    await expect(result2).not.toBeVisible();
  });
});
